import {panel as pwaPanel,act as pwaAct} from './pwa.js';
import {createVocabularyShelf,wordDetails} from './vocabulary-shelf.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7M5 9v11h5v-6h4v6h5V9',book:'M12 5v16M12 5C8 2 4 3 2 4v15c4-1 7-1 10 2 3-3 6-3 10-2V4c-4-1-7-2-10 1',grammar:'M4 4h16v16H4zM8 9h8M8 13h5M8 17h3',chart:'M4 3v17h17M8 15v-4M13 15V7M18 15v-6',folder:'M3 6h7l2 3h9v11H3zM3 6V4h7l2 2h8v3',settings:'M4 7h16M4 17h16M8 4v6M16 14v6',arrow:'M5 12h14m-5-5 5 5-5 5',back:'M19 12H5m5-5-5 5 5 5',check:'m5 12 4 4L19 6',clock:'M12 7v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',refresh:'M20 7V3l-3 3M4 17v4l3-3M20 7a8 8 0 0 0-14-3M4 17a8 8 0 0 0 14 3',fire:'M12 2c2 5-1 7 3 9l2-5c7 8 4 16-5 16S0 14 6 9c-1 4 3 6 4 3s0-5 2-10',spark:'m12 2 2.6 7.4L22 12l-7.4 2.6L12 22l-2.6-7.4L2 12l7.4-2.6z',leaf:'M20 3C7 1 2 7 5 15s15 7 15-12ZM5 20 16 8',calendar:'M4 5h16v16H4zM8 3v4M16 3v4M4 10h16',upload:'M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6',download:'M12 3v13m-5-5 5 5 5-5M4 15v6h16v-6',close:'m6 6 12 12M18 6 6 18',external:'M14 3h7v7M21 3l-10 10M10 3H3v18h18v-7',plus:'M12 4v16M4 12h16',volume:'M11 4 5 9H2v6h3l6 5zM15 8c3 2 3 6 0 8M18 5c5 4 5 10 0 14',edit:'m4 16-1 5 5-1L21 7l-4-4zM14 6l4 4',shield:'m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6zM8 12l3 3 5-6',target:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0M12 10v4M10 12h4',headphones:'M3 13v-2a9 9 0 0 1 18 0v2M3 12h4v8H3zM17 12h4v8h-4z'};
const icon=(name,extra='')=>`<svg class="icon ${extra}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;
const routes=[['today','今日学习','home','今日'],['words','词汇练习','book','词汇'],['grammar','语法练习','grammar','语法'],['progress','雅思进度','chart','进度'],['mistakes','错题本','folder','错题'],['data','数据与设置','settings','数据'],['library','本地资料库','book','资料'],['ai','AI 学习伙伴','spark','AI'],['more','更多学习','settings','更多']];
let storageProblem='',badRaw=null,toastTimer,state,session=null,grammarSession=null,skillTab='听力',filter='全部',showResolved=false,showAllRecords=false,pendingImport=null,manualRetry=null,viewDate=C.today();
try{const raw=localStorage.getItem(C.STORAGE_KEY);state=raw?C.validateState(JSON.parse(raw)):C.freshState();}catch(error){try{badRaw=localStorage.getItem(C.STORAGE_KEY);}catch{}state=C.freshState();storageProblem=badRaw?'已保留无法读取的旧数据；请在“数据”页下载旧数据，再导入有效备份。当前练习暂不覆盖旧数据。':'浏览器暂时无法保存数据。请允许网站存储，并及时导出本次学习。';}
C.ensureDay(state);
function persist(){if(badRaw)return;try{localStorage.setItem(C.STORAGE_KEY,JSON.stringify(state));}catch{storageProblem='本次学习尚未写入浏览器（存储受限或空间不足）。请立即在“数据”页导出备份。';showStorageWarning();}}
function commit(fn){
 if(!badRaw&&!storageProblem){try{const current=localStorage.getItem(C.STORAGE_KEY);if(current)state=C.validateState(JSON.parse(current));}catch{storageProblem='其他窗口的数据无法读取，本页学习暂存于内存。请立即导出备份。';}}
 C.ensureDay(state);const result=fn(state);persist();return result;
}
persist();
function showStorageWarning(){$('#storage-warning').hidden=!storageProblem;$('#storage-warning').textContent=storageProblem;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3400);}
function route(){const value=location.hash.slice(1);return routes.some(r=>r[0]===value)?value:'today';}
function go(name){if(route()===name)render();else location.hash=name;}
function head(eyebrow,title,subtitle,extra=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtext">${subtitle}</p></div>${extra}</div>`;}
function fmtDate(date){return `${Number(date.slice(5,7))} 月 ${Number(date.slice(8))} 日`;}
function button(label,action,extra='',cls='btn'){return `<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;}
function empty(title,text,action=''){return `<div class="glass empty">${icon('leaf')}<h2>${title}</h2><p>${text}</p>${action}</div>`;}
function openDialog(title,body,actions=''){$('#dialog').innerHTML=`<div class="dialog-head"><h2>${title}</h2>${button(icon('close'),'close-dialog','aria-label="关闭对话框"','icon-btn')}</div><div class="dialog-content">${body}</div>${actions?`<div class="dialog-actions">${actions}</div>`:''}`;$('#dialog').showModal();}
function closeDialog(){$('#dialog').close();}
function nav(){
 const current=route(),count=state.mistakes.filter(m=>!m.resolved).length;
 $('#sidebar').innerHTML=`<a class="brand" href="#today" aria-label="YAN English Studio 首页"><img src="./icon.svg" alt=""><div><strong>YAN</strong><small>ENGLISH STUDIO</small></div></a><div class="nav-label">YOUR LEARNING SPACE</div><nav class="nav-links">${routes.filter(x=>!['data','more'].includes(x[0])).map(([id,name,i])=>`<a class="nav-link ${current===id?'active':''}" ${current===id?'aria-current="page"':''} href="#${id}">${icon(i)}<span>${name}</span>${id==='mistakes'&&count?`<span class="count">${count}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="goal-note">${icon('leaf','leaf')}<strong>慢慢来，也是在前进。</strong><small>A little progress, every day.</small></div><a class="nav-link ${current==='data'?'active':''}" href="#data" ${current==='data'?'aria-current="page"':''}>${icon('settings')}<span>数据与设置</span></a><div class="sidebar-foot"><i class="dot"></i>你的学习，由你珍藏</div></div>`;
 $('#topbar').innerHTML=`<div class="breadcrumb">我的学习空间<span>/</span><span>${routes.find(x=>x[0]===current)[1]}</span></div><a href="#today" class="mobile-brand" aria-label="YAN English Studio 首页"><img src="./icon.svg" alt=""><span>YAN<small>ENGLISH STUDIO</small></span></a><div class="top-actions"><span class="local-status"><i class="dot"></i>${storageProblem?'请导出备份':'本地保存'}</span><a href="#data" class="icon-btn" aria-label="打开数据备份与设置">${icon('shield')}</a><div class="avatar" aria-hidden="true">Y</div></div>`;
 $('#mobile-nav').innerHTML=[...routes.slice(0,5),routes.find(x=>x[0]==='more')].map(([id,name,i,short])=>`<a href="#${id}" class="mobile-link ${current===id||(id==='more'&&['data','library','ai'].includes(current))?'active':''}" aria-label="${name}" ${current===id?'aria-current="page"':''}>${icon(i)}<span>${short}</span></a>`).join('');
 document.title=`${routes.find(x=>x[0]===current)[1]} · YAN English Studio`;
 showStorageWarning();
}
function render(){
 C.ensureDay(state);nav();
 const content={today:dashboard,words:wordsPage,grammar:grammarPage,progress:progressPage,mistakes:mistakesPage,data:dataPage,library:extras.library,ai:extras.aiPage,more:extras.more}[route()]();
 $('#main').innerHTML=content;
 if(route()==='today')$('#main').insertAdjacentHTML('afterbegin','<div class="quick-learning"><a href="#library">本地资料库 ↗</a><a href="#ai">AI 学习伙伴 ↗</a></div>');
 if(route()==='words'&&session?.phase==='spell')setTimeout(()=>$('#spelling')?.focus({preventScroll:true}),80);
}
const illustration=`<div class="hero-art" aria-hidden="true"><svg viewBox="0 0 270 235"><defs><linearGradient id="book-grad" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#fcfcf4"/><stop offset="1" stop-color="#c5d6d9"/></linearGradient><linearGradient id="arch-grad" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#bfd0d5" stop-opacity=".3"/><stop offset="1" stop-color="#92b0b8" stop-opacity=".65"/></linearGradient></defs><circle cx="172" cy="70" r="60" fill="#f8faf2" opacity=".35"/><path d="M99 177V93a57 57 0 0 1 114 0v84" fill="url(#arch-grad)" stroke="#fff" stroke-opacity=".5"/><path d="M119 175V98a37 37 0 0 1 74 0v77" fill="none" stroke="#edf4ef" stroke-opacity=".5"/><ellipse cx="139" cy="194" rx="92" ry="14" fill="#88a8b3" opacity=".15"/><path d="m53 166 81 25 81-31-81-24z" fill="#95b2bd"/><path d="m53 159 81 25 81-31-81-24z" fill="#e8efec" stroke="#d1dddd"/><path d="m55 152 79 24 78-30-79-23z" fill="#fcfcf5"/><path d="m69 128 68 24 66-29-67-22z" fill="#7f9faa"/><path d="m69 120 68 24 66-29-67-22z" fill="url(#book-grad)"/><path d="m137 144 0 8" stroke="#5c7d8d"/><path d="m87 116 47 17 42-18" stroke="#b5c8cc" fill="none"/><path d="M159 104c1-23 9-35 15-46" fill="none" stroke="#809c8c" stroke-width="2"/><path d="M165 78c-22 1-26-14-24-22 21 0 26 12 24 22M170 68c19 0 25-14 23-23-19 0-26 14-23 23" fill="#9fb6a5"/><path d="M160 94c-17 3-27-8-25-17 17-3 26 7 25 17" fill="#b1c3af"/><circle cx="69" cy="77" r="7" fill="#f5f5e9"/><path d="m218 90 3 7 7 3-7 3-3 7-3-7-7-3 7-3z" fill="#f5f7ec"/><circle cx="91" cy="43" r="2" fill="#b0c3c4"/></svg><small>GROW AT YOUR OWN PACE</small></div>`;
function dashboard(){
 const date=C.today(),d=state.days[date],stats=C.dailyStats(state),pending=C.dueIds(state).length,hour=new Date().getHours(),greeting=hour<12?'早上好':hour<18?'下午好':'晚上好';
 const days=Array.from({length:7},(_,i)=>C.addDays(date,i-6)),remaining=C.daysBetween(date,state.settings.targetDate);
 const items=[{n:'01',icon:'book',title:'认识 20 个新朋友',desc:'看释义 · 读例句 · 练拼写',progress:stats.vocab,total:d.newIds.length,action:'start-new',label:d.newIds.length?`${stats.vocab} / ${d.newIds.length} 个新词`:'本词库已学完',color:'blue'},{n:'02',icon:'refresh',title:'让记忆更牢一点',desc:'按记忆表现，复习到期单词',progress:stats.review,total:d.reviewIds.length,action:'start-review',label:pending?`${pending} 个单词待复习`:'今天暂无到期单词'},{n:'03',icon:'grammar',title:'一句一句，建立语感',desc:'5 道练习 · 从时态与否定句开始',progress:stats.grammar,total:5,action:'start-grammar',label:`${stats.grammar} / 5 道语法题`},{n:'04',icon:'headphones',title:'向雅思，再靠近一步',desc:'任选一项听、读、写、说练习',progress:Math.min(stats.records,1),total:1,action:'go-progress',label:stats.records?'已留下今天的练习记录':'完成练习后，记下一笔'}];
 return head('A LITTLE PROGRESS, EVERY DAY',`${greeting}，YAN <span style="font-size:21px;color:#a6b4aa">✦</span>`,'今天也为自己，积攒一点小小的进步。',`<div class="date-chip">${icon('calendar')}<span>${fmtDate(date)} · ${['周日','周一','周二','周三','周四','周五','周六'][new Date().getDay()]}</span></div>`)+`<section class="hero"><div class="hero-content"><div class="hero-label"><i class="dot"></i>YOUR DAILY CHAPTER</div><h2>Small steps.<br><em>A brighter tomorrow.</em></h2><p>不必一下子学会所有。<br>从今天的 20 个单词开始，慢慢靠近你的目标。</p><div class="hero-actions">${button(`继续我的学习 ${icon('arrow')}`,'continue')}${button('我的学习计划 ↗','show-plan','','text-btn')}</div></div>${illustration}</section><section class="stats" aria-label="学习概况"><div class="stat glass"><div class="stat-icon">${icon('book')}</div><div><div class="stat-value">${stats.vocab}<small>/ ${d.newIds.length}</small></div><div class="stat-label">今日新词</div></div></div><div class="stat glass"><div class="stat-icon">${icon('refresh')}</div><div><div class="stat-value">${pending}<small>个</small></div><div class="stat-label">到期复习</div></div></div><div class="stat glass"><div class="stat-icon">${icon('fire')}</div><div><div class="stat-value">${C.streak(state)}<small>天</small></div><div class="stat-label">连续学习</div></div></div><div class="stat glass"><div class="stat-icon">${icon('spark')}</div><div><div class="stat-value">${stats.xp}<small>XP</small></div><div class="stat-label">今日成长值</div></div></div></section><div class="dashboard-grid"><section><div class="section-head"><div><h2>今天，学这些就好</h2><p>YOUR DAILY LITTLE WINS</p></div><span class="pill">${stats.completed} / ${stats.tasks.length} 项已完成</span></div><div class="tasks">${items.map(t=>`<article class="task-card glass"><div class="task-top"><div class="task-icon">${icon(t.icon)}</div><span class="task-number">${t.n}</span></div><h3>${t.title}</h3><p>${t.desc}</p><div class="task-bottom"><span>${t.label}</span>${button(icon(t.total&&t.progress>=t.total?'check':'arrow'),t.action,`aria-label="${t.title}"`,'circle-link')}</div><div class="progress-track" role="progressbar" aria-label="${t.title}" aria-valuenow="${t.progress}" aria-valuemin="0" aria-valuemax="${t.total||1}"><div class="progress-fill" style="width:${t.total?Math.min(100,t.progress/t.total*100):0}%"></div></div></article>`).join('')}</div><p class="caption">${stats.percent}% 的今日计划已完成。完成练习会自动记录，不需要额外打卡。</p></section><aside class="dashboard-aside"><section class="week-card glass"><div class="section-head"><h3>和学习，保持联系</h3>${icon('calendar')}</div><div class="week-days">${days.map(day=>`<div class="week-day ${day===date?'today':''} ${state.days[day]?.activities?'active':''}" aria-label="${day} ${state.days[day]?.activities?'已学习':'尚无学习记录'}"><span>${['日','一','二','三','四','五','六'][new Date(day+'T12:00:00').getDay()]}</span><div class="day-circle">${state.days[day]?.activities?'✓':Number(day.slice(8))}</div></div>`).join('')}</div><p class="encourage">${state.days[date].activities?'今天的努力，已经被好好记住。':'做一道题，就点亮今天的小圆点。'}</p></section><section class="goal-card"><div class="eyebrow">YOUR NORTH STAR</div><h3>IELTS Academic</h3><div class="goal-numbers"><strong>${state.settings.targetBand.toFixed(1)}</strong><span>→ 6.5</span></div><p>${remaining>=0?`距 ${fmtDate(state.settings.targetDate)} 目标还有 ${remaining} 天`:'目标日期已到，可在设置中调整'}<br>先稳住基础，再向前一步。</p></section><p class="quote">“Little by little, a little becomes a lot.”</p></aside></div>`;
}
function startWords(mode,onlyId=null){
 commit(()=>{});const day=state.days[C.today()];
 const ids=onlyId?[onlyId]:mode==='new'?day.newIds.filter(id=>!day.wordDone.includes(id)):mode==='review'?C.dueIds(state):[...new Set(state.mistakes.filter(m=>m.category==='拼写'&&!m.resolved&&m.refId).map(m=>m.refId))];
 session={mode,ids,index:0,phase:mode==='spelling'?'spell':'front',answer:'',correct:null,date:C.today()};
 go('words');
}
function wordsPage(){
 if(session)return wordExercise();
 const d=state.days[C.today()],newCount=d.newIds.filter(id=>!d.wordDone.includes(id)).length,due=C.dueIds(state).length,spelling=state.mistakes.filter(m=>m.category==='拼写'&&!m.resolved&&m.refId).length;
 return head('WORDS THAT STAY WITH YOU','让单词，慢慢变熟悉','先认识，再回忆。拼错的单词会自动进入错题本。')+`<div class="mode-grid">${[{name:'今天的新词',count:newCount,text:'每天 20 个，从日常表达走向学术基础。',i:'book',action:'start-new',label:'开始认识新词'},{name:'到期复习',count:due,text:'根据记忆表现安排，让遗忘慢一点。',i:'refresh',action:'start-review',label:'唤醒已有记忆'},{name:'拼写巩固',count:spelling,text:'看中文写英文，把容易混淆的拼写练稳。',i:'edit',action:'start-spelling',label:'重练易错拼写'}].map(m=>`<button class="mode-card" data-action="${m.action}">${icon(m.i)}<strong>${m.name}</strong><div class="big">${m.count}</div><p>${m.text}</p><div class="mode-start">${m.label}${icon('arrow')}</div></button>`).join('')}</div><section class="panel glass"><div class="panel-head"><h2>你的学习词库</h2><span class="pill blue">${Object.keys(state.cards).length} / ${WORDS.length} 个已接触</span></div><p class="body-copy">${WORDS.length} 个词，覆盖 ${new Set(WORDS.map(w=>w.topic)).size} 个主题，约 ${Math.ceil(WORDS.length/20)} 组每日新词。学完后会明确提示词库已完成；仍可继续间隔复习。漏学的词会留给后续学习，不会自动算作掌握。</p><details class="vocabulary-topics"><summary>查看全部学习主题</summary><div class="topic-tags">${[...new Set(WORDS.map(w=>w.topic))].map(t=>`<span class="tag">${t}</span>`).join('')}</div></details><p class="caption">原创例句卡与 ECDICT 开源扩展词典分别标注。拼写练习按卡片展示的词形核对。</p></section>${vocabularyShelf.view()}${reviewPreview()}<div class="notice">复习规则：不会 / 模糊 → 明天；连续记住 → 1、3、7、14、30、60 天后。拼写错误时，本次“记住”按“模糊”安排。此规则是简单学习辅助，不代表已科学测定你的记忆。</div>`;
}
function reviewPreview(){
 const grouped={};for(const card of Object.values(state.cards)){grouped[card.due]=(grouped[card.due]||0)+1;}
 const dates=Object.keys(grouped).sort().slice(0,7);
 if(!dates.length)return '';
 return '<section class="panel glass"><h2>接下来的复习安排</h2><p class="caption">日期会随每次记忆选择更新；逾期单词会一直保留在到期复习中。</p><div class="topic-tags">'+dates.map(d=>'<span class="tag">'+fmtDate(d)+(d<=C.today()?' · 已到期':'')+' · '+grouped[d]+' 个词</span>').join('')+'</div></section>';
}
function wordExercise(){
 const {ids,index,phase,mode}=session;
 if(index>=ids.length){return completion(ids.length?`${ids.length} 个单词，认真见过了。`:'这一组已完成',ids.length?'本次进度已保存。不会与模糊的单词会继续出现在后续复习中。':mode==='new'?(Object.keys(state.cards).length===WORDS.length?`${WORDS.length} 个学习词均已接触，接下来继续复习与巩固。`:'今天的新词已完成，明天会安排下一组。'):mode==='review'?'今天暂无到期单词，可以先学习新词或做语法练习。':'当前没有待重练的拼写错误。',button('返回词汇空间','exit-words','','btn secondary')+button(`继续语法 ${icon('arrow')}`,'start-grammar'));}
 const word=WORDS.find(w=>w.id===ids[index]);
 const top=`<div class="exercise-toolbar">${button(`${icon('back')} 词汇空间`,'exit-words','','text-btn')}<span>${mode==='new'?'今日新词':mode==='review'?'间隔复习':mode==='explore'?'自主练习':'拼写重练'} · ${index+1} / ${ids.length}</span></div><div class="progress-track" style="margin-bottom:20px"><div class="progress-fill" style="width:${index/ids.length*100}%"></div></div>`;
 let body='';
 if(phase==='front')body=`<div class="eyebrow">${esc(word.topic)} · LOOK & RECALL</div><div class="word" lang="en">${word.word}</div><p class="exercise-prompt">先在心里想一想，它是什么意思？</p>${button(word.source==='ecdict'?'查看词典释义':'查看释义与例句','reveal-word','','btn secondary')}<div class="exercise-bottom"><span class="caption">先回忆，再揭晓。慢一点没关系。</span></div>`;
 if(phase==='back')body=`<div class="eyebrow">${esc(word.topic)}</div><div class="word" lang="en">${word.word}</div><div class="word-meaning">${esc(word.meaning)}</div>${word.phonetic?`<p class="word-phonetic" lang="en">${esc(word.phonetic)}</p>`:''}${wordDetails(word,esc)}${button(`试着拼写 ${icon('arrow')}`,'spell-word')}<p class="caption">下一步会隐藏英文，用中文回忆单词。</p>`;
 if(phase==='spell')body=`<div class="eyebrow">RECALL & SPELL</div><h2 style="font-size:24px;margin:30px 0 12px">${esc(word.meaning)}</h2><p class="spelling-hint">根据中文，写出刚才学的单词。</p><form class="spell-form" id="spell-form"><label class="skip-link" for="spelling">输入英文单词</label><input id="spelling" name="answer" placeholder="Type the word…" lang="en" autocomplete="off" autocapitalize="none" spellcheck="false" required maxlength="100" aria-label="输入英文单词"><button class="btn" type="submit">检查拼写</button></form>${button('暂时想不起来','skip-spelling','','text-btn')}<p class="caption">大小写不影响结果；词尾、字母顺序需要准确。</p>`;
 if(phase==='result'){
  const prev=state.cards[word.id],next=C.schedule(prev,'good').due;
  body=`<div class="eyebrow">ONE MORE STEP FORWARD</div><div class="word" lang="en">${word.word}</div><div class="word-meaning">${esc(word.meaning)}</div><div class="feedback ${session.correct?'':'error'} reward"><strong>${session.correct?'✓ 拼写正确，做得不错。':'这次先记住它的正确拼写。'}</strong><p>${session.correct?'继续回忆，会越来越熟悉。':`你的拼写：${esc(session.answer||'（未作答）')}\n正确拼写：${word.word}`}</p>${!session.correct?'<small>已加入拼写错题本；本次“记住”会按“模糊”安排。</small>':''}</div><p class="spelling-hint">现在，你对这个单词有多熟悉？</p><div class="rating-buttons">${button('不会<span>明天再见</span>','rate-word','data-rating="again"','rating')}${button('模糊<span>明天巩固</span>','rate-word','data-rating="fuzzy"','rating fuzzy')}${button(`记住<span>${session.correct?C.daysBetween(C.today(),next):1} 天后复习</span>`,'rate-word','data-rating="good"','rating good')}</div>`;
 }
 return `<div class="exercise-wrap">${top}<section class="exercise-card glass">${body}</section><p class="caption">${word.source==='ecdict'?'ECDICT 词典条目 · MIT · 非官方 IELTS 词表':CONTENT_LABEL} · 完成记忆选择后自动保存进度。</p></div>`;
}
function completion(title,text,actions){return `<div class="exercise-wrap"><div class="glass completion reward"><div class="completion-icon">${icon('check')}</div><div class="eyebrow">A LITTLE WIN, WELL EARNED</div><h2 style="margin-top:12px">${title}</h2><p>${text}</p><div class="actions">${actions}</div></div></div>`;}
function startGrammar(id=null){commit(()=>{});grammarSession={ids:id?[id]:C.grammarQueue(state),index:0,selected:null,submitted:false,correct:null,date:C.today()};go('grammar');}
function grammarPage(){
 if(!grammarSession)return head('ONE SENTENCE AT A TIME','把基础，一句一句练稳','一次只做一道。错了就看解析，再给自己一次机会。')+`<section class="hero"><div class="hero-content"><div class="hero-label">YOUR FOUNDATION FIRST</div><h2>Good grammar.<br><em>Built little by little.</em></h2><p>今天先练 5 题，重点照顾时态和否定句。<br>已经完成 ${Math.min(5,state.days[C.today()].grammarDone.length)} / 5 题。</p>${button(`开始今日练习 ${icon('arrow')}`,'start-grammar')}</div>${illustration}</section><div class="panel glass"><h2>从这些容易混淆的地方开始</h2><div class="topic-tags">${['doesn’t + 动词原形','didn’t + 动词原形','be 动词否定','一般现在时','过去时与现在完成时','名词与介词'].map(x=>`<span class="tag">${x}</span>`).join('')}</div><p class="caption">${GRAMMAR.length} 道${CONTENT_LABEL}。每日优先安排较少练习的题目，做错后可在错题本重练。</p></div>`;
 const s=grammarSession;if(s.index>=s.ids.length)return completion(s.ids.length?'这几句话，又清楚了一点。':'今天的 5 道语法练习已完成','答案和错因已保存。做错的题目留在错题本，可以随时回来重练。',button('查看错题本','go-mistakes','','btn secondary')+button('记录一项雅思练习','go-progress'));
 const q=GRAMMAR.find(x=>x.id===s.ids[s.index]);
 return `<div class="exercise-wrap"><div class="exercise-toolbar">${button(`${icon('back')} 语法空间`,'exit-grammar','','text-btn')}<span>今日语法 · ${s.index+1} / ${s.ids.length}</span></div><section class="exercise-card glass"><div class="eyebrow">${esc(q.topic)}</div><h2 class="question-prompt">${esc(q.prompt)}</h2><div class="question-options" role="group" aria-label="请选择答案">${q.options.map((o,i)=>`<button class="option ${s.selected===i?'selected':''} ${s.submitted&&i===q.answer?'right':''} ${s.submitted&&s.selected===i&&i!==q.answer?'wrong':''}" data-action="select-answer" data-option="${i}" aria-pressed="${s.selected===i}" ${s.submitted?'disabled':''}><span class="letter">${String.fromCharCode(65+i)}</span><span>${esc(o)}</span>${s.submitted&&i===q.answer?icon('check'):''}</button>`).join('')}</div>${s.submitted?`<div class="feedback ${s.correct?'':'error'} reward"><strong>${s.correct?'✓ 回答正确':'再看一眼，这样理解就清楚了。'}</strong><p>${esc(q.explanation)}</p><small>${esc(q.translation)}</small>${!s.correct?'<small>已自动加入语法错题本。</small>':''}</div>`:''}<div class="exercise-nav">${s.submitted?button(`${s.index===s.ids.length-1?'完成本组':'下一题'} ${icon('arrow')}`,'next-grammar'):button('检查答案','check-grammar',s.selected===null?'disabled':'')}</div></section><p class="caption">${CONTENT_LABEL} · 解析用于基础训练，不代表官方评分。</p></div>`;
}
function progressPage(){
 const ordered=[...state.records].sort((a,b)=>b.date.localeCompare(a.date)), skillRecords=ordered.filter(r=>r.skill===skillTab), recent=skillRecords.slice(0,6), displayed=showAllRecords?skillRecords:recent,raw=['听力','阅读'].includes(skillTab);
 return head('YOUR JOURNEY, IN YOUR OWN WORDS','每一次练习，都有迹可循','记录真实表现，找到下一次练习的方向。')+`<div class="stats">${C.SKILLS.map((skill,i)=>{const r=ordered.find(x=>x.skill===skill);return `<div class="stat glass"><div class="stat-icon">${icon(['headphones','book','edit','volume'][i])}</div><div><div class="stat-value">${r?(['听力','阅读'].includes(skill)?`${r.correct}<small>/ ${r.total}</small>`:`${state.records.filter(x=>x.skill===skill).length}<small>次</small>`):'—'}</div><div class="stat-label">${skill} · ${i<2?'最近正确题数':'练习记录'}</div></div></div>`}).join('')}</div><div class="split"><section class="panel glass"><div class="panel-head"><h2>记下今天的练习</h2><span class="pill blue">本地学习日志</span></div><div class="skill-tabs" aria-label="练习类型">${C.SKILLS.map(t=>`<button class="skill-tab ${skillTab===t?'active':''}" data-action="skill-tab" data-skill="${t}" aria-pressed="${skillTab===t}">${t}</button>`).join('')}</div><form id="record-form"><div class="form-grid"><div class="field full"><label for="record-title">${raw?'练习材料 / 试卷名称':'练习题目'} *</label><input id="record-title" name="title" required maxlength="200" placeholder="${raw?'如：官方 Academic 样题 · Section 1':'如：描述一次旅行 / Task 1 柱状图'}"></div><div class="field"><label for="record-date">练习日期</label><input id="record-date" type="date" name="date" value="${C.today()}" max="${C.today()}" min="2000-01-01" required></div><div class="field"><label for="record-minutes">练习用时（分钟）</label><input id="record-minutes" type="number" name="minutes" min="1" max="1440" step="1" value="20" required inputmode="numeric"></div>${raw?`<div class="field"><label for="record-correct">实际正确题数 *</label><input id="record-correct" name="correct" type="number" min="0" max="40" step="1" required inputmode="numeric" placeholder="0–40"></div><div class="field"><label for="record-total">总题数 *</label><input id="record-total" name="total" type="number" min="1" max="40" step="1" required value="40" inputmode="numeric"></div>`:''}<div class="field full"><label for="record-feedback">${raw?'错因与发现（选填）':'练习反馈 / 自评 *'}</label><textarea id="record-feedback" name="feedback" maxlength="3000" ${raw?'':'required'} placeholder="${raw?'如：复数词尾没听清；阅读定位花了太久。':'如：能表达主要意思，但过去时经常漏掉。也可粘贴老师的反馈。'}"></textarea></div><div class="field full"><label for="record-next">下次只改进一件事（选填）</label><input id="record-next" name="nextAction" maxlength="500" placeholder="如：多留意过去时 / 每段先找主题句"></div></div><p class="field-error" id="record-error" role="alert"></p><div class="notice">${raw?'只记录实际正确题数与正确率，不自动换算 IELTS Band 分。不同练习的难度和总题数可能不同。':'写作与口语反馈来自你的输入，也可保存 AI 辅导页的建议。模型建议明确标记，不提供官方雅思成绩。'}</div><button class="btn" type="submit">${icon('plus')} 保存练习记录</button></form></section><section><div class="panel glass"><div class="panel-head"><h2>${skillTab} · 最近的脚印</h2><span class="pill">${state.records.filter(x=>x.skill===skillTab).length} 次练习</span></div>${recent.length?`${raw?`<div class="bars" aria-label="最近六次练习正确率">${[...recent].reverse().map(r=>`<div class="bar-item"><span>${Math.round(r.correct/r.total*100)}%</span><div class="bar-track"><div class="bar" style="height:${r.correct/r.total*100}%"></div></div><span>${r.date.slice(5)}</span></div>`).join('')}</div><p class="caption">正确率趋势 · 非 Band 分数</p><div class="divider"></div>`:''}<div class="record-list">${displayed.map(recordCard).join('')}</div>${skillRecords.length>6?button(showAllRecords?'收起历史记录':`查看全部 ${skillRecords.length} 条记录`,'toggle-records','','text-btn'):''}`:`<div class="empty" style="padding:25px 10px">${icon('chart')}<h3>第一笔记录，从今天开始。</h3><p style="margin-top:10px;margin-bottom:0">完成一项${skillTab}练习后，在左侧或上方填写。这里会慢慢长出你的学习轨迹。</p></div>`}</div><div class="panel glass"><h3>需要练习材料？</h3><p class="caption">以下为官方免费练习入口，外部网站可能需要联网。本站不转载试卷或冒充官方题库。</p>${resourceLinks()}</div></section></div>`;
}
function recordCard(r){return `<article class="record-item"><div class="record-top"><span class="pill blue">${r.skill}</span><span class="muted">${r.date} · ${r.minutes} 分钟</span></div><h3>${esc(r.title)}</h3>${r.feedback?`<p>${esc(r.feedback)}</p>`:''}${r.nextAction?`<p>下次：${esc(r.nextAction)}</p>`:''}<div class="record-foot"><span class="record-score">${r.correct!==null?`${r.correct}<small> / ${r.total} 题</small>`:''}</span>${button('删除','delete-record',`data-id="${esc(r.id)}"`,'text-btn')}</div></article>`;}
function resourceLinks(){return `<div class="sources"><a class="source-link" href="https://ielts.org/take-a-test/preparation-resources/sample-test-questions/academic-test" target="_blank" rel="noopener noreferrer"><span>IELTS 官方 · Academic 样题<br><small>听力 / 阅读 / 写作 / 口语</small></span>${icon('external')}</a><a class="source-link" href="https://takeielts.britishcouncil.org/prepare/ielts-free-practice-mock-tests" target="_blank" rel="noopener noreferrer"><span>British Council · 免费练习<br><small>官方备考材料与练习入口</small></span>${icon('external')}</a></div>`;}
function mistakesPage(){
 const ms=state.mistakes.filter(m=>(filter==='全部'||m.category===filter)&&(showResolved||!m.resolved));
 return head('MISTAKES ARE PART OF LEARNING','把错过的，再学会一次','这里记录需要多照顾一下的知识点。练对之后，自动移入已巩固。')+`<div class="toolbar"><div class="filters" style="margin-bottom:0">${['全部',...C.CATEGORIES].map(cat=>button(`${cat} <span style="opacity:.7">${state.mistakes.filter(m=>(cat==='全部'||m.category===cat)&&!m.resolved).length}</span>`,'filter-mistakes',`data-category="${cat}" aria-pressed="${cat===filter}"`,`filter ${cat===filter?'active':''}`)).join('')}</div>${button(`${icon('plus')} 手动记一题`,'add-mistake','','btn secondary')}</div><label class="check-label" style="margin-bottom:20px"><input id="show-resolved" type="checkbox" ${showResolved?'checked':''}>也显示已巩固的题目</label>${ms.length?`<div class="mistake-grid">${ms.map(m=>`<article class="mistake-card glass"><div class="meta"><span class="pill ${m.resolved?'':'warm'}">${m.category}${m.resolved?' · 已巩固':''}</span><span>遇到 ${m.count} 次 · ${m.lastAt.slice(5)}</span></div><h3>${esc(m.prompt)}</h3><p>上次作答：${esc(m.userAnswer||'（未记录）')}</p><div class="actions">${button(`重新练习 ${icon('arrow')}`,'retry-mistake',`data-id="${esc(m.id)}"`,'btn secondary')}${button('问 AI','ask-mistake',`data-id="${esc(m.id)}"`,'text-btn')}</div></article>`).join('')}</div>`:empty('这里暂时很安静。',filter==='阅读'||filter==='听力'?'做完外部练习后，点“手动记一题”保存题目、正确答案和错因，就可以在这里重练。':'做错的拼写和语法题、记忆模糊的单词会自动收录。你也可以手动添加听力或阅读错题。')}`;
}
function dataPage(){
 const active=Object.values(state.days).filter(d=>d.activities>0).length;
 return head('A SAFE PLACE FOR YOUR PROGRESS','学习数据，由你保管','建议每周导出一次，也在更换设备或清理浏览器前备份。')+`${badRaw?`<div class="notice warm">旧数据无法读取，已停止覆盖。${button('下载保留的旧数据','export-raw','','link-button')}</div>`:''}<div class="data-grid"><section class="data-card glass">${icon('download')}<h2>带走你的每一点进步</h2><p>导出一份 JSON 文件，包含单词记忆、复习日期、练习记录、错题和学习天数。</p><div class="data-summary"><div><strong>${active}</strong><span>学习天数</span></div><div><strong>${Object.keys(state.cards).length}</strong><span>已接触单词</span></div><div><strong>${state.records.length}</strong><span>雅思练习</span></div></div>${button(`${icon('download')} 导出学习备份`,'export-data')}<p class="caption" style="margin:13px 0 0">${state.lastExport?`上次发起导出：${state.lastExport}（请确认文件已下载）`:'还没有导出过，第一份备份可以从现在开始。'}</p></section><section class="data-card glass">${icon('upload')}<h2>接着上一次，继续学</h2><p>此备份包含词汇、错题与练习记录。陪伴对话和影音笔记请在对应页面单独导出。先核对摘要，再确认导入。导入会替换此浏览器中的现有学习数据。</p><div class="field"><label for="import-file">选择 JSON 备份</label><input id="import-file" type="file" accept=".json,application/json"></div><div class="notice">导入前会在此浏览器保留一份原数据，可用下面的按钮恢复。跨设备使用时，请手动导出、传输并导入；不会自动同步。</div>${button('恢复上一次导入前的数据','restore-backup','','btn ghost')}</section></div><section class="panel glass" style="margin-top:20px"><div class="panel-head"><h2>我的学习目标</h2><span class="pill blue">IELTS Academic</span></div><form id="settings-form" class="settings-row"><div class="field"><label for="target-date">阶段目标日期</label><input id="target-date" type="date" name="targetDate" required value="${state.settings.targetDate}"></div><div class="field"><label for="target-band">当前目标分数</label><select id="target-band" name="targetBand"><option value="6" ${state.settings.targetBand===6?'selected':''}>6.0 · 先稳住基础</option><option value="6.5" ${state.settings.targetBand===6.5?'selected':''}>6.5 · 下一阶段</option></select></div><button class="btn secondary" type="submit">保存目标</button></form><p class="caption">初始目标为 2026 年 11 月 30 日前冲刺 6.0，后续目标 6.5。这里展示学习计划，不承诺考试结果。</p></section><section class="panel glass"><h2>关于这个小小的学习空间</h2><div class="body-copy"><ul><li>v1.4 · 独立项目。${WORDS.length} 个基础词、${GRAMMAR.length} 道语法题、32 份原创学习示例（AI 辅助编写），非雅思真题；资料库另有官方与精选资源、私人影音练习。</li><li>学习数据只保存在当前设备、当前浏览器、当前网站地址下。无痕模式结束或清理网站数据可能丢失记录。</li><li>可选连接本机 Ollama 或已有兼容 API，连接状态以 AI 页实际检测为准。没有自动同步、记忆系统连接或官方雅思评分。</li><li>连续学习天数按有实际练习的自然日计算；今日未学时保留截至昨天的连续天数。日期以设备本地日期为准。</li><li>新词、到期复习、语法与技能记录完成后自动更新今日进度。不会或拼错，也算认真完成了练习。</li></ul></div>${resourceLinks()}</section>`;
}
function submitSpelling(answer){if(!session||session.phase!=='spell')return;session.answer=answer;session.correct=commit(s=>C.recordSpelling(s,session.ids[session.index],answer));session.phase='result';render();}
function addMistakeDialog(){openDialog('给这个知识点，留一张便签',`<form id="mistake-form"><div class="field"><label for="mistake-category">分类</label><select id="mistake-category" name="category">${C.CATEGORIES.map(c=>`<option ${c===(['阅读','听力'].includes(filter)?filter:'阅读')?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label for="mistake-prompt">题目 / 题目编号与上下文 *</label><textarea id="mistake-prompt" name="prompt" maxlength="3000" required placeholder="写下题目，或记录材料名称、题号和需要回忆的内容"></textarea></div><div class="field"><label for="mistake-answer">正确答案 *</label><input id="mistake-answer" name="answer" maxlength="1000" required></div><div class="field"><label for="mistake-wrong">我的错误答案</label><input id="mistake-wrong" name="userAnswer" maxlength="1000"></div><div class="field"><label for="mistake-note">为什么错 / 下次注意什么</label><textarea id="mistake-note" name="note" maxlength="3000"></textarea></div><div class="dialog-actions"><button class="btn" type="submit">保存到错题本</button></div></form>`);}
function retryMistake(id){const m=state.mistakes.find(x=>x.id===id);if(!m)return;if(m.refId&&m.category==='语法'){closeDialog();startGrammar(m.refId);}else if(m.refId){closeDialog();startWords(m.category==='拼写'?'spelling':'review',m.refId);}else{manualRetry={id,revealed:false};openDialog(`${m.category} · 重新回忆`,`<p style="white-space:pre-wrap">${esc(m.prompt)}</p><form id="manual-retry-form"><div class="field"><label for="retry-answer">先写下你的答案</label><textarea id="retry-answer" name="answer" required maxlength="1000"></textarea></div><div class="dialog-actions"><button class="btn" type="submit">查看答案并核对</button></div></form>`);}}
function download(name,text){const url=URL.createObjectURL(new Blob([text],{type:'application/json;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function previewImport(candidate,source='文件'){
 pendingImport=candidate;const active=Object.values(candidate.days).filter(d=>d.activities>0).length;
 openDialog('核对这份学习备份',`<p>来源：${source}。确认后将替换当前浏览器的学习数据，不会合并。</p><div class="import-preview">学习天数：${active} 天<br>已接触单词：${Object.keys(candidate.cards).length} 个<br>错题记录：${candidate.mistakes.length} 条<br>雅思练习：${candidate.records.length} 次<br>阶段目标：${candidate.settings.targetDate}</div><p>当前数据会先保留为“导入前备份”。建议额外导出文件，再继续。</p>`,button('取消','close-dialog','','btn secondary')+button('确认替换并导入','confirm-import'));
}
function handleAction(action,el){
 if(pwaAct(action))return;
 if(vocabularyShelf.act(action,el))return;
 if(extras.act(action,el))return;
 if(action==='ask-mistake'){const m=state.mistakes.find(x=>x.id===el.dataset.id);if(m)extras.askMistake(m);return;}
 if(C.today()!==viewDate){viewDate=C.today();session=null;grammarSession=null;commit(()=>{});render();toast('新的一天开始了，已刷新学习任务。');return;}
 switch(action){
 case 'continue': {const d=state.days[C.today()];if(C.dueIds(state).length)startWords('review');else if(d.newIds.some(id=>!d.wordDone.includes(id)))startWords('new');else if(d.grammarDone.length<5)startGrammar();else go('progress');break;}
 case 'start-new':startWords('new');break;
 case 'start-review':startWords('review');break;
 case 'start-spelling':startWords('spelling');break;
 case 'exit-words':session=null;render();break;
 case 'reveal-word':session.phase='back';render();break;
 case 'spell-word':session.phase='spell';render();break;
 case 'skip-spelling':submitSpelling('');break;
 case 'rate-word':{if(session?.phase!=='result')return;const next=commit(s=>C.rateWord(s,session.ids[session.index],el.dataset.rating,session.mode,C.today(),session.correct));session.index++;session.phase=session.mode==='spelling'?'spell':'front';session.answer='';session.correct=null;render();toast(`已保存 · ${fmtDate(next.due)} 再复习`);break;}
 case 'start-grammar':startGrammar();break;
 case 'exit-grammar':grammarSession=null;render();break;
 case 'select-answer':if(grammarSession&&!grammarSession.submitted){grammarSession.selected=Number(el.dataset.option);render();}break;
 case 'check-grammar':{const s=grammarSession;if(!s||s.submitted||s.selected===null)return;s.correct=commit(st=>C.answerGrammar(st,s.ids[s.index],s.selected));s.submitted=true;render();break;}
 case 'next-grammar':grammarSession.index++;grammarSession.selected=null;grammarSession.submitted=false;grammarSession.correct=null;render();break;
 case 'go-progress':go('progress');break;
 case 'go-mistakes':go('mistakes');break;
 case 'skill-tab':skillTab=el.dataset.skill;showAllRecords=false;render();break;
 case 'toggle-records':showAllRecords=!showAllRecords;render();break;
 case 'filter-mistakes':filter=el.dataset.category;render();break;
 case 'add-mistake':addMistakeDialog();break;
 case 'retry-mistake':retryMistake(el.dataset.id);break;
 case 'manual-result':{const m=manualRetry;if(!m?.revealed)return;const correct=el.dataset.result==='correct';commit(s=>{const found=s.mistakes.find(x=>x.id===m.id);found.resolved=correct;found.lastAt=C.today();if(!correct){found.count++;found.userAnswer=m.answer;}C.ensureDay(s).activities++;});closeDialog();render();toast(correct?'已移入已巩固，继续加油。':'已保留在错题本，下次再练。');break;}
 case 'delete-record':openDialog('删除这条练习记录？','<p>删除后，相关日期的技能任务进度会重新计算。学习活动天数仍保留。</p>',button('保留','close-dialog','','btn secondary')+button('确认删除','confirm-delete',`data-id="${esc(el.dataset.id)}"`));break;
 case 'confirm-delete':commit(s=>{s.records=s.records.filter(r=>r.id!==el.dataset.id);});closeDialog();render();toast('记录已删除。');break;
 case 'export-data':commit(s=>{s.lastExport=C.today();});download(`YAN-English-backup-${C.today()}.json`,JSON.stringify(C.exportEnvelope(state),null,2));render();toast('已发起备份下载，请确认文件已保存。');break;
 case 'export-raw':download(`YAN-preserved-data-${C.today()}.json`,badRaw||'{}');break;
 case 'confirm-import':{if(!pendingImport)return;try{const candidate=C.validateState(pendingImport);localStorage.setItem(C.BACKUP_KEY,JSON.stringify(state));localStorage.setItem(C.STORAGE_KEY,JSON.stringify(candidate));state=candidate;badRaw=null;storageProblem='';C.ensureDay(state);persist();session=null;grammarSession=null;pendingImport=null;extras.reset();closeDialog();render();toast('备份已导入，欢迎接着学。');}catch(e){toast(`导入未完成：${e.message}`);}break;}
 case 'restore-backup':try{const raw=localStorage.getItem(C.BACKUP_KEY);if(!raw){toast('暂时没有导入前的备份。');break;}previewImport(C.validateState(JSON.parse(raw)),'上一次导入前的自动备份');}catch(e){toast(`备份无法读取：${e.message}`);}break;
 case 'close-dialog':closeDialog();pendingImport=null;break;
 case 'show-plan':openDialog('每天一点，走向 6.0',`<div class="body-copy"><p>阶段目标：${state.settings.targetDate} · IELTS Academic ${state.settings.targetBand.toFixed(1)}</p><ul><li>约 20 分钟：到期词优先，再学 20 个新词。看中文回忆英文，完成拼写测试。</li><li>约 10 分钟：5 道语法练习。特别留意 doesn’t / didn’t 后的动词原形。</li><li>约 20–30 分钟：听、读、写、说选一项，使用官方材料练习，并记录真实表现。</li><li>约 5 分钟：重练错题。每周导出一次备份，检查最常出现的错误。</li></ul><p>时间为起步建议，可以按精力拆成几段。完成练习自动积累进度与成长值。</p></div>`,button('开始今天的学习','plan-start'));break;
 case 'plan-start':closeDialog();handleAction('continue',el);break;
 }
}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(el&&!el.disabled){try{handleAction(el.dataset.action,el);}catch(error){toast(error.message||'操作未完成，请重试。');}}});
document.addEventListener('submit',event=>{
 const form=event.target;event.preventDefault();const values=Object.fromEntries(new FormData(form));
 if(vocabularyShelf.submit(form,values))return;
 if(['library-search','library-quiz','shelf-search','ai-config-form','ai-tutor','ai-pair-form','chat-form','chat-import-form'].includes(form.id)){extras.submit(form,values);return;}
 if(C.today()!==viewDate){viewDate=C.today();session=null;grammarSession=null;commit(()=>{});render();toast('日期已更新，请从新一天的任务继续。');return;}
 try{
 if(form.id==='spell-form')submitSpelling(values.answer);
 if(form.id==='record-form'){commit(s=>C.addRecord(s,{...values,skill:skillTab,correct:values.correct==null?null:Number(values.correct),total:values.total==null?null:Number(values.total),minutes:Number(values.minutes)}));render();toast('记录已保存，今天又前进了一步。');}
 if(form.id==='settings-form'){if(!C.validDate(values.targetDate))throw new Error('请选择有效的日期。');commit(s=>{s.settings.targetDate=values.targetDate;s.settings.targetBand=Number(values.targetBand);});render();toast('学习目标已更新。');}
 if(form.id==='mistake-form'){if(!values.prompt.trim()||!values.answer.trim())throw new Error('请填写题目和正确答案。');commit(s=>C.mistake(s,{...values,refId:null}));closeDialog();render();toast('已经放进错题本了。');}
 if(form.id==='manual-retry-form'){const m=state.mistakes.find(x=>x.id===manualRetry.id);manualRetry.revealed=true;manualRetry.answer=values.answer;closeDialog();openDialog('核对答案，再判断一次',`<p style="white-space:pre-wrap">${esc(m.prompt)}</p><div class="feedback"><strong>参考答案：${esc(m.answer)}</strong><p>${esc(m.note||'没有补充解析。')}</p></div><p>本次作答：${esc(values.answer)}</p><p>这是手动收录的题目，请自行核对内容与含义。系统不会冒充 AI 判分。</p>`,button('还需要练习','manual-result','data-result="wrong"','btn secondary')+button('我已答对','manual-result','data-result="correct"'));}
 }catch(error){if(form.id==='record-form')$('#record-error').textContent=error.message;else toast(error.message);}
});
document.addEventListener('change',async event=>{
 if(event.target.id==='show-resolved'){showResolved=event.target.checked;render();}
 if(event.target.id==='import-file'){
  const file=event.target.files?.[0];if(!file)return;
  try{if(file.size>8*1024*1024)throw new Error('备份文件超过 8 MB，请检查文件。');previewImport(C.parseBackup(await file.text()),esc(file.name));}catch(error){toast(error.message);}
  event.target.value='';
 }
});
window.addEventListener('hashchange',()=>{extras.leave();render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});});
window.addEventListener('storage',event=>{if(event.key===C.STORAGE_KEY&&event.newValue){try{state=C.validateState(JSON.parse(event.newValue));session=null;grammarSession=null;render();toast('已更新同一浏览器中另一窗口的学习进度。');}catch{toast('另一窗口的数据无法读取，请检查备份。');}}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&viewDate!==C.today()){viewDate=C.today();session=null;grammarSession=null;commit(()=>{});render();toast('今天的新任务准备好了。');}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
const extras=createExtras({esc,head,button,icon,commit,toast,go,render,route,download});
const vocabularyShelf=createVocabularyShelf({esc,button,render,open:id=>{if(WORDS.some(w=>w.id===id))startWords('explore',id);}});
window.addEventListener('yan-pwa-change',()=>{const panel=$('.pwa-panel');if(panel)panel.outerHTML=pwaPanel();});
document.addEventListener('input',extras.input);
document.addEventListener('change',extras.input);
render();
